#include <stdio.h>

int main(void) {
    int A, B, C, D;
    if (scanf("%d", &A) != 1) return 0;
    if (scanf("%d", &B) != 1) return 0;
    if (scanf("%d", &C) != 1) return 0;
    if (scanf("%d", &D) != 1) return 0;

    /*
     * Procuramos k >= 0 tal que o volume de leite L = C - k*D satisfaca:
     *     A <= C - k*D <= B
     * <=> C - B <= k*D <= C - A
     *
     * O candidato ideal e o maior multiplo de D que nao excede C - A:
     *     k = floor((C - A) / D)
     * Se esse multiplo ainda atinge C - B, existe solucao; caso contrario,
     * nenhum multiplo de D cai no intervalo.
     */
    long long k = (long long)(C - A) / D;
    long long milk_low = (long long)C - B;
    long long milk_max_coffee = k * D;

    if (milk_max_coffee >= milk_low) {
        puts("S");
    } else {
        puts("N");
    }
    return 0;
}
